"""Runs sql/questions.sql against outputs/pms.db and writes docs/sql_results.md."""
import re
import sqlite3
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
con = sqlite3.connect(ROOT / "outputs" / "pms.db")
text = (ROOT / "sql" / "questions.sql").read_text()
out = ["# SQL examples and results", "",
       "*Generated by `scripts/run_questions.py` from `sql/questions.sql` on the replay run.*", ""]
for block in re.split(r"^-- name: ", text, flags=re.M)[1:]:
    title, sql = block.split("\n", 1)
    sql = sql.strip()
    cur = con.execute(sql)
    cols = [d[0] for d in cur.description]
    rows = cur.fetchall()
    out += [f"## {title.strip()}", "", "```sql", sql, "```", "",
            "| " + " | ".join(cols) + " |", "|" + " --- |" * len(cols)]
    out += ["| " + " | ".join("" if v is None else str(v) for v in r) + " |" for r in rows]
    out.append("")
(ROOT / "docs" / "sql_results.md").write_text("\n".join(out), encoding="utf-8")
print("written docs/sql_results.md")
